 options float=hard, CPU=68020      program float      parameter CONST1 = 3.141597e0      parameter CONST2 = 1.783903E4      parameter COUNT = 1000      real a, b, c      integer i      equivalence (a, f7), (b, f6), (c, f5)      equivalence (i, d7)           a = CONST1      b = CONST2      do i = 1, COUNT        c = a * b        c = c / a        c = a * b        c = c / a        c = a * b        c = c / a        c = a * b        c = c / a        c = a * b        c = c / a        c = a * b        c = c / a        c = a * b        c = c / a      end do      call shell('procs', i)      end